SELECT DATE_FORMAT(created_at, #{fmt}) AS time_bucket, COUNT(*) AS total, SUM(CASE WHEN status = 'FAIL' THEN 1 ELSE 0 END) AS failed FROM report_ai WHERE family_id = #{familyId} AND created_at >= #{start} AND created_at < #{end}
AND feature_code IN #{f}
GROUP BY time_bucket ORDER BY time_bucket
